// Fotografa os totais antes de qualquer request da coleção criar dados
const base = pm.environment.get("baseUrl");
const counts = {};

pm.test("status 200", () => pm.response.to.have.status(200));

pm.test("owners: total inicial lido", () => {
  pm.expect(pm.response.json()).to.be.an("array");
});
counts.owners = pm.response.json().length;
pm.collectionVariables.set("countsBefore", JSON.stringify(counts));

["pets", "pettypes", "visits"].forEach((resource) => {
  pm.sendRequest(base + "/" + resource, (err, res) => {
    pm.test(resource + ": total inicial lido", () => {
      pm.expect(err).to.be.null;
      pm.expect(res.code).to.eql(200);
      pm.expect(res.json()).to.be.an("array");
    });
    counts[resource] = res.json().length;
    pm.collectionVariables.set("countsBefore", JSON.stringify(counts));
  });
});

// Valor esperado vem do que foi enviado, nunca da própria resposta
const sent = JSON.parse(pm.variables.replaceIn(pm.request.body.raw));
const body = pm.response.json();

pm.test("status 201", () => pm.response.to.have.status(201));

pm.test("campos iguais aos enviados", () => {
  ["firstName", "lastName", "address", "city", "telephone"].forEach((field) => {
    pm.expect(body[field], field).to.eql(sent[field]);
  });
});

pm.test("id gerado é um número", () => {
  pm.expect(body.id).to.be.a("number");
});

pm.test("responde em menos de 500 ms", () => {
  pm.expect(pm.response.responseTime).to.be.below(500);
});

// Usado pelos próximos requests do fluxo
pm.collectionVariables.set("ownerId", body.id);

// Quantos donos existem antes do POST (a API como espelho do banco; o banco direto fica para o pytest)
pm.sendRequest(pm.environment.get("baseUrl") + "/owners", (err, res) => {
  pm.collectionVariables.set("ownersCountBefore", res.json().length);
});

// Campo omitido neste request
const field = "firstName";

const sent = JSON.parse(pm.request.body.raw);
const countBefore = Number(pm.collectionVariables.get("ownersCountBefore"));

pm.test("corpo enviado não tem o campo " + field, () => {
  pm.expect(sent).to.not.have.property(field);
});

pm.test("status 400", () => pm.response.to.have.status(400));

// O 400 tem de ser pelo campo que falta, não por outro
pm.test("erro aponta o campo " + field, () => {
  const errors = pm.response.json().schemaValidationErrors;
  pm.expect(errors, "lista de erros de validação").to.be.an("array").and.not.empty;
  errors.forEach((e) => pm.expect(e.field).to.eql(field));
});

pm.test("responde em menos de 500 ms", () => {
  pm.expect(pm.response.responseTime).to.be.below(500);
});

// Nenhum dono pode ter sido criado
pm.sendRequest(pm.environment.get("baseUrl") + "/owners", (err, res) => {
  pm.test("quantidade de donos não mudou", () => {
    pm.expect(err).to.be.null;
    pm.expect(res.json().length).to.eql(countBefore);
  });
});

