// Cria tipo, dono, pet e visita deste teste e guarda os totais depois disso
const base = pm.environment.get("baseUrl");

function post(path, data, next) {
  pm.sendRequest({
    url: base + path,
    method: "POST",
    header: { "Content-Type": "application/json" },
    body: { mode: "raw", raw: JSON.stringify(data) }
  }, (err, res) => {
    if (err) throw err;
    if (res.code !== 201) throw new Error("Preparação falhou: POST " + path + " devolveu " + res.code);
    next(res.json());
  });
}

function saveCounts(resources, counts) {
  if (resources.length === 0) {
    pm.collectionVariables.set("cascadeCountsBefore", JSON.stringify(counts));
    return;
  }
  pm.sendRequest(base + "/" + resources[0], (err, res) => {
    if (err) throw err;
    counts[resources[0]] = res.json().length;
    saveCounts(resources.slice(1), counts);
  });
}

post("/pettypes", { name: "tartaruga" }, (type) => {
  pm.collectionVariables.set("cascadeTypeId", type.id);
  const owner = { firstName: "Clara", lastName: "Lima", address: "Rua do Sol, 30", city: "Olinda", telephone: "8199990010" };
  post("/owners", owner, (createdOwner) => {
    const ownerId = createdOwner.id;
    pm.collectionVariables.set("cascadeOwnerId", ownerId);
    const pet = { name: "Rex", birthDate: "2020-05-10", type: { id: type.id, name: type.name } };
    post("/owners/" + ownerId + "/pets", pet, (createdPet) => {
      pm.collectionVariables.set("cascadePetId", createdPet.id);
      const visit = { date: "2026-11-01", description: "Consulta de rotina" };
      post("/owners/" + ownerId + "/pets/" + createdPet.id + "/visits", visit, (createdVisit) => {
        pm.collectionVariables.set("cascadeVisitId", createdVisit.id);
        saveCounts(["owners", "pets", "visits"], {});
      });
    });
  });
});

