function oldestAllowedDate() {
  const now = new Date();
  const month = now.getUTCMonth();
  const limit = new Date(Date.UTC(now.getUTCFullYear() - 50, month, now.getUTCDate()));
  // 29 de fevereiro vira 28 quando o ano do limite não é bissexto
  if (limit.getUTCMonth() !== month) limit.setUTCDate(0);
  return limit;
}

