const base = pm.environment.get("baseUrl");
const ownerPath = "/owners/" + pm.collectionVariables.get("ownerId") + "/pets";
const type = { id: Number(pm.collectionVariables.get("petTypeId")), name: pm.collectionVariables.get("petTypeName") };

function post(path, data, next) {
  pm.sendRequest({
    url: base + path,
    method: "POST",
    header: { "Content-Type": "application/json" },
    body: { mode: "raw", raw: JSON.stringify(data) }
  }, (err, res) => {
    if (err) throw err;
    if (res.code !== 201) throw new Error("Preparação falhou: POST " + path + " devolveu " + res.code);
    next(res.json());
  });
}

function saveCounts(resources, counts) {
  if (resources.length === 0) {
    pm.collectionVariables.set("visitedPetCountsBefore", JSON.stringify(counts));
    return;
  }
  pm.sendRequest(base + "/" + resources[0], (err, res) => {
    if (err) throw err;
    counts[resources[0]] = res.json().length;
    saveCounts(resources.slice(1), counts);
  });
}

post(ownerPath, { name: "Rex", birthDate: "2020-05-10", type: type }, (pet) => {
  pm.collectionVariables.set("visitedPetId", pet.id);
  const visitsPath = ownerPath + "/" + pet.id + "/visits";
  post(visitsPath, { date: "2026-11-01", description: "Consulta de rotina" }, (first) => {
    post(visitsPath, { date: "2026-11-02", description: "Retorno" }, (second) => {
      pm.collectionVariables.set("visitedPetVisitIds", JSON.stringify([first.id, second.id]));
      post(ownerPath, { name: "Bidu", birthDate: "2020-05-10", type: type }, (sibling) => {
        pm.collectionVariables.set("siblingPetId", sibling.id);
        post(ownerPath + "/" + sibling.id + "/visits", { date: "2026-11-03", description: "Vacina" }, (visit) => {
          pm.collectionVariables.set("siblingVisitId", visit.id);
          saveCounts(["pets", "visits"], {});
        });
      });
    });
  });
});

