// Numa execução normal, o pet do teste e as visitas dele já saíram (404).
const base = pm.environment.get("baseUrl");
const steps = [{ path: "visits", id: pm.collectionVariables.get("siblingVisitId") }]
  .concat(JSON.parse(pm.collectionVariables.get("visitedPetVisitIds")).map((id) => ({ path: "visits", id: id })))
  .concat([
    { path: "pets", id: pm.collectionVariables.get("visitedPetId") },
    { path: "pets", id: pm.collectionVariables.get("siblingPetId") }
  ]);

function checkDeleted(code, step) {
  pm.test(step.path + "/" + step.id + ": apagado ou já removido (204 ou 404)", () => {
    pm.expect(code).to.be.oneOf([204, 404]);
  });
}

function confirmGone(index) {
  const step = steps[index];
  pm.sendRequest(base + "/" + step.path + "/" + step.id, (err, res) => {
    pm.test(step.path + "/" + step.id + ": não existe mais (GET devolve 404)", () => {
      pm.expect(err).to.be.null;
      pm.expect(res.code).to.eql(404);
    });

    const next = steps[index + 1];
    if (!next) return;
    pm.sendRequest({ url: base + "/" + next.path + "/" + next.id, method: "DELETE" }, (delErr, delRes) => {
      if (delErr) throw delErr;
      checkDeleted(delRes.code, next);
      confirmGone(index + 1);
    });
  });
}

checkDeleted(pm.response.code, steps[0]);
confirmGone(0);

