const base = pm.environment.get("baseUrl");
const saved = pm.collectionVariables.get("countsBefore");

// Apaga a foto para uma execução seguinte nunca comparar com dados antigos
pm.collectionVariables.unset("countsBefore");

pm.test("status 200", () => pm.response.to.have.status(200));

pm.test("totais iniciais disponíveis (rode antes o CT-API-INTEGRITY-01a)", () => {
  pm.expect(saved, "countsBefore").to.be.a("string").and.not.empty;
});

const before = saved ? JSON.parse(saved) : {};

pm.test("owners: mesmo total do início", () => {
  pm.expect(pm.response.json().length).to.eql(before.owners);
});

["pets", "pettypes", "visits"].forEach((resource) => {
  pm.sendRequest(base + "/" + resource, (err, res) => {
    pm.test(resource + ": mesmo total do início", () => {
      pm.expect(err).to.be.null;
      pm.expect(res.code).to.eql(200);
      pm.expect(res.json().length).to.eql(before[resource]);
    });
  });
});
